/**
 * The body a MUTATION hands back, and the reply its callbacks are driven with.
 *
 * A screen calls m.mutate(vars, { onSuccess, onError }) and everything that
 * matters lives in those two closures — firstMatchingRule, the chain runner,
 * ruleNav, ruleHandled, the fall-through navigate. A mock whose mutate did
 * nothing reached the press and stopped there, which is why a screen with an
 * API binding sat around 50% covered while its render was fully exercised.
 *
 * mutateReply is what the callbacks receive, and the suite steps it through
 * every rule the DESIGN declares so each arm is reached with a body that can
 * actually match it — a rule firing on status 409 is unreachable with a 200.
 */
const mutateReply: { body: Record<string, unknown>; status: number; fail: boolean } = {
  body: { code: 'OK', status: 20, machineId: 'm-1' },
  status: 200,
  fail: false,
};

/** Deliver the callbacks react-query would, in the order it would. */
const deliver = (vars: unknown, opts?: Record<string, unknown>): void => {
  const call = (name: string, ...args: unknown[]): void => {
    const fn = opts?.[name];
    if (typeof fn === 'function') (fn as (...a: unknown[]) => unknown)(...args);
  };
  if (mutateReply.fail) {
    const err = new AppError('server', 'boom', { status: mutateReply.status });
    call('onError', err, vars, undefined);
    call('onSettled', undefined, err, vars, undefined);
    return;
  }
  const body = { ...mutateReply.body, __status: mutateReply.status };
  call('onSuccess', body, vars, undefined);
  call('onSettled', body, null, vars, undefined);
};

